//! anbani-core: the Georgian script and language toolkit, Rust core.
//!
//! Byte-identical to anbani.js and anbani.py of the same MAJOR.MINOR on the shared golden suite (`spec/golden.json`): script
//! conversion between Mkhedruli, Mtavruli, Asomtavruli, Nuskhuri, the bicameral styles and every romanisation table,
//! script classification, Kartvelian Morse, georgianisation, contractions, tokenisation, letter numerals, text statistics and lorem.
//!
//! `no_std` + `alloc`; no dependencies. Tables are generated by `tools/gen.py` from canonical neutral data;
//! `data/manifest.json` records source-specific provenance and licenses.
#![no_std]
#![forbid(unsafe_code)]

extern crate alloc;
#[cfg(feature = "std")]
extern crate std;

pub mod art;
pub mod chars;
pub mod convert;
#[cfg(test)]
mod equivalence;
pub mod error;
pub mod generated;
pub mod inspect;
#[cfg(feature = "legacy")]
pub mod legacy;
pub mod lorem;
pub mod morph;
pub mod morse;
pub mod nlp;
pub mod normalize;
pub mod numbers;
pub mod numerals;
pub mod phon;
pub mod scheme;
pub mod script;
pub mod toolkit;

pub use convert::{convert, convert_with, interpret, Options};
pub use error::Error;
pub use script::classify;

/// Crate version (the workspace version).
pub const VERSION: &str = env!("CARGO_PKG_VERSION");
